from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NradjgnbParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.nradjgnb_ent = self.enb_ent_config['nradjgnb'][self.mo_num]

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        mcc, mnc = self.nradjgnb_ent['mcc'], self.nradjgnb_ent['mnc']

        self.set_struct_parameter('gnbPlmn', [
            {
                'mcc': mcc,
                'mnc': mnc,
                'mncLength': self.get_len_str(mnc),
            }
        ])
        self.set_parameter('gNodeBId', self.nradjgnb_ent['gnb_id'])
        self.set_parameter('administrativeState', 'Unlocked')
        self.set_parameter('gNodeBIdCtrl', 'gnbControlled')
